   681  static UA_StatusCode
   682  processCompleteChunkWithoutChannel(UA_Server *server, UA_Connection *connection,
   683                                     UA_ByteString *message) {
   684      /* Process chunk without a channel; must be OPN */
   685      UA_LOG_TRACE(server->config.logger, UA_LOGCATEGORY_NETWORK,
   686                   "Connection %i | No channel attached to the connection. "
   687                   "Process the chunk directly", connection->sockfd);
   688      size_t offset = 0;
   689      UA_TcpMessageHeader tcpMessageHeader;
   690      UA_StatusCode retval =
   691          UA_TcpMessageHeader_decodeBinary(message, &offset, &tcpMessageHeader);
   692      if(retval != UA_STATUSCODE_GOOD)
   693          return retval;
   694
   695      // Only HEL and OPN messages possible without a channel (on the server side)
   696      switch(tcpMessageHeader.messageTypeAndChunkType & 0x00ffffff) {
   697      case UA_MESSAGETYPE_HEL:
   698          retval = processHEL(server, connection, message, &offset);
   699          break;
   700      case UA_MESSAGETYPE_OPN:
   701      {
   702          UA_LOG_TRACE(server->config.logger, UA_LOGCATEGORY_NETWORK,
   703                       "Connection %i | Process OPN message", connection->sockfd);
   704
   705          /* Called before HEL */
   706          if(connection->state != UA_CONNECTION_ESTABLISHED) {
   707              retval = UA_STATUSCODE_BADCOMMUNICATIONERROR;
   708              break;
   709          }
   710
   711          // Decode the asymmetric algorithm security header since it is not encrypted and
   712          // needed to decide what security policy to use.
   713          UA_AsymmetricAlgorithmSecurityHeader asymHeader;
   714          UA_AsymmetricAlgorithmSecurityHeader_init(&asymHeader);
   715          size_t messageHeaderOffset = UA_SECURE_CONVERSATION_MESSAGE_HEADER_LENGTH;
   716          retval = UA_AsymmetricAlgorithmSecurityHeader_decodeBinary(message,
   717                                                                     &messageHeaderOffset,
   718                                                                     &asymHeader);
   719          if(retval != UA_STATUSCODE_GOOD)
   720              break;
   721
   722          retval = createSecureChannel(server, connection, &asymHeader);
   723          UA_AsymmetricAlgorithmSecurityHeader_deleteMembers(&asymHeader);
   724          if(retval != UA_STATUSCODE_GOOD)
   725              break;
   726
   727          retval = UA_SecureChannel_decryptAddChunk(connection->channel, message, UA_FALSE);
   728          if(retval != UA_STATUSCODE_GOOD)
   729              break;
   730
   731          UA_SecureChannel_processCompleteMessages(connection->channel, server,
   732                                                   processSecureChannelMessage);
   733          break;
   734      }
   735      default:
   736          UA_LOG_TRACE(server->config.logger, UA_LOGCATEGORY_NETWORK,
   737                       "Connection %i | Expected OPN or HEL message on a connection "
   738                       "without a SecureChannel", connection->sockfd);
   739          retval = UA_STATUSCODE_BADTCPMESSAGETYPEINVALID;
   740          break;
   741      }
   742      return retval;
   743  }
