   954  UA_StatusCode
   955  UA_SecureChannel_processCompleteMessages(UA_SecureChannel *channel, void *application,
   956                                           UA_ProcessMessageCallback callback) {
   957      UA_Message *message, *tmp_message;
   958      UA_StatusCode retval = UA_STATUSCODE_GOOD;
   959      TAILQ_FOREACH_SAFE(message, &channel->messages, pointers, tmp_message) {
   960          /* Stop at the first incomplete message */
   961          if(!message->final)
   962              break;
   963
   964          /* Remove the current message before processing */
   965          TAILQ_REMOVE(&channel->messages, message, pointers);
   966
   967          /* Process */
   968          retval = processMessage(channel, message, application, callback);
   969          if(retval != UA_STATUSCODE_GOOD)
   970              break;
   971
   972          /* Clean up the message */
   973          UA_ChunkPayload *payload;
   974          while((payload = SIMPLEQ_FIRST(&message->chunkPayloads))) {
   975              if(payload->copied)
   976                  UA_ByteString_deleteMembers(&payload->bytes);
   977              SIMPLEQ_REMOVE_HEAD(&message->chunkPayloads, pointers);
